import sys

data = sys.stdin.read().split()
n = int(data[0])
m = int(data[1])
g = [list(map(int, data[2 + i * m:2 + (i + 1) * m])) for i in range(n)]
d = [[0] * m for _ in range(n)]
for i in range(n):
    for j in range(m):
        if g[i][j] == 1:
            d[i][j] = 0
        elif i == 0 and j == 0:
            d[i][j] = 1
        else:
            d[i][j] = (d[i - 1][j] if i else 0) + (d[i][j - 1] if j else 0)
print(d[n - 1][m - 1])

